use std::f64::consts::PI;

pub type Point = [f64; 2];
pub type Ring = Vec<Point>;
pub type Polygon = Vec<Ring>;

pub fn build_polygon(n: i32) -> Polygon {
    let vertex_count = n.saturating_mul(3);
    let count = if vertex_count > 0 {
        vertex_count as usize
    } else {
        0
    };

    let mut ring = Vec::with_capacity(count);
    if vertex_count > 0 {
        let divisor = f64::from(vertex_count);
        for i in 0..count {
            let angle = 2.0 * PI * (i as f64) / divisor;
            ring.push([angle.cos(), angle.sin()]);
        }
    }

    vec![ring]
}

pub fn signed_area(ring: &[Point]) -> f64 {
    if ring.len() < 3 {
        return 0.0;
    }

    let mut twice_area = 0.0;
    for i in 0..ring.len() {
        let current = ring[i];
        let next = ring[(i + 1) % ring.len()];
        twice_area += current[0] * next[1] - next[0] * current[1];
    }

    twice_area * 0.5
}

pub fn cross(a: Point, b: Point, c: Point) -> f64 {
    (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0])
}

