use std::io::{self, Write};

use super::atoi::parse_i32;
use super::geometry::build_polygon;
use super::triangulation::earcut;

pub fn run<I, S>(args: I) -> io::Result<()>
where
    I: IntoIterator<Item = S>,
    S: AsRef<str>,
{
    let mut stdout = io::stdout().lock();
    stdout.write_all(render_from_args(args).as_bytes())
}

pub fn render_output(arg: Option<&str>) -> String {
    let mut args = vec![String::from("test1")];
    if let Some(value) = arg {
        args.push(value.to_string());
    }
    render_from_args(args)
}

fn render_from_args<I, S>(args: I) -> String
where
    I: IntoIterator<Item = S>,
    S: AsRef<str>,
{
    let mut args = args.into_iter();
    let _program = args.next();
    let n = args.next().map(|value| parse_i32(value.as_ref())).unwrap_or(1);

    let polygon = build_polygon(n);
    let indices = earcut(&polygon);

    let mut output = String::new();
    for index in indices {
        output.push_str(&index.to_string());
        output.push(' ');
    }

    output
}

